Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
scsi: qla2xxx: edif: Fix n2n discovery issue with secure
 target

User failed to see disk via n2n topology. Driver used up all login retries
before authentication application started. When authentication application
started, driver did not have enough login retries to connect securely. On
app_start, driver will reset the login retry attempt count.

Link: https://lore.kernel.org/r/20220607044627.19563-10-njavali@marvell.com
Fixes: 4de067e5df12 ("scsi: qla2xxx: edif: Add N2N support for EDIF")
Signed-off-by: Quinn Tran <qutran@marvell.com>
Signed-off-by: Nilesh Javali <njavali@marvell.com>
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The bug was caused by the driver exhausting all login retries before the authentication application started, which prevented the driver from establishing a secure connection. When the authentication application initiated, the driver did not have any remaining login retries to connect securely, leading to the failure in disk visibility via the n2n topology.

Here is the patch:
  */
 static int
 qla_edif_app_start(scsi_qla_host_t *vha, struct bsg_job *bsg_job)
 {
 	int32_t			rval = 0;
 	struct fc_bsg_reply	*bsg_reply = bsg_job->reply;
 	struct app_start	appstart;
 	struct app_start_reply	appreply;
 	struct fc_port  *fcport, *tf;

 	ql_log(ql_log_info, vha, 0x1313,
 	       "EDIF application registration with driver, FC device connections will be re-established.\n");

 	sg_copy_to_buffer(bsg_job->request_payload.sg_list,
 	    bsg_job->request_payload.sg_cnt, &appstart,
 	    sizeof(struct app_start));

 	ql_dbg(ql_dbg_edif, vha, 0x911d, "%s app_vid=%x app_start_flags %x\n",
 	     __func__, appstart.app_info.app_vid, appstart.app_start_flags);

 	if (DBELL_INACTIVE(vha)) {
 		/* mark doorbell as active since an app is now present */
 		vha->e_dbell.db_flags |= EDB_ACTIVE;
 	} else {
 		ql_dbg(ql_dbg_edif, vha, 0x911e, "%s doorbell already active\n",
 		     __func__);
 	}

 	if (N2N_TOPO(vha->hw)) {
+		list_for_each_entry_safe(fcport, tf, &vha->vp_fcports, list)
+			fcport->n2n_link_reset_cnt = 0;
+
 		if (vha->hw->flags.n2n_fw_acc_sec)
 			set_bit(N2N_LINK_RESET, &vha->dpc_flags);
 		else
 			set_bit(ISP_ABORT_NEEDED, &vha->dpc_flags);
 		qla2xxx_wake_dpc(vha);
 	} else {
 		list_for_each_entry_safe(fcport, tf, &vha->vp_fcports, list) {
 			ql_dbg(ql_dbg_edif, vha, 0x2058,
 			       "FCSP - nn %8phN pn %8phN portid=%06x.\n",
 			       fcport->node_name, fcport->port_name,
 			       fcport->d_id.b24);
 			ql_dbg(ql_dbg_edif, vha, 0xf084,
 			       "%s: se_sess %p / sess %p from port %8phC "
 			       "loop_id %#04x s_id %06x logout %d "
 			       "keep %d els_logo %d disc state %d auth state %d"
 			       "stop state %d\n",
 			       __func__, fcport->se_sess, fcport,
 			       fcport->port_name, fcport->loop_id,
 			       fcport->d_id.b24, fcport->logout_on_delete,
 			       fcport->keep_nport_handle, fcport->send_els_logo,
 			       fcport->disc_state, fcport->edif.auth_state,
 			       fcport->edif.app_stop);

 			if (atomic_read(&vha->loop_state) == LOOP_DOWN)
 				break;

 			fcport->login_retry = vha->hw->login_retry_count;

 			fcport->edif.app_stop = 0;
 			fcport->edif.app_sess_online = 0;

 			if (fcport->scan_state != QLA_FCPORT_FOUND)
 				continue;

 			if (fcport->port_type == FCT_UNKNOWN &&
 			    !fcport->fc4_features)
 				rval = qla24xx_async_gffid(vha, fcport, true);

 			if (!rval && !(fcport->fc4_features & FC4_FF_TARGET ||
 			    fcport->port_type & (FCT_TARGET|FCT_NVME_TARGET)))
 				continue;

 			rval = 0;

 			ql_dbg(ql_dbg_edif, vha, 0x911e,
 			       "%s wwpn %8phC calling qla_edif_reset_auth_wait\n",
 			       __func__, fcport->port_name);
 			qlt_schedule_sess_for_deletion(fcport);
 			qla_edif_sa_ctl_init(vha, fcport);
 		}
 	}

 	if (vha->pur_cinfo.enode_flags != ENODE_ACTIVE) {
 		/* mark as active since an app is now present */
 		vha->pur_cinfo.enode_flags = ENODE_ACTIVE;
 	} else {
 		ql_dbg(ql_dbg_edif, vha, 0x911f, "%s enode already active\n",
 		     __func__);
 	}

 	appreply.host_support_edif = vha->hw->flags.edif_enabled;
 	appreply.edif_enode_active = vha->pur_cinfo.enode_flags;
 	appreply.edif_edb_active = vha->e_dbell.db_flags;
 	appreply.version = EDIF_VERSION1;

 	bsg_job->reply_len = sizeof(struct fc_bsg_reply);

 	SET_DID_STATUS(bsg_reply->result, DID_OK);

 	bsg_reply->reply_payload_rcv_len = sg_copy_from_buffer(bsg_job->reply_payload.sg_list,
 							       bsg_job->reply_payload.sg_cnt,
 							       &appreply,
 							       sizeof(struct app_start_reply));

 	ql_dbg(ql_dbg_edif, vha, 0x911d,
 	    "%s app start completed with 0x%x\n",
 	    __func__, rval);

 	return rval;
 }



